using System.IO;
using System.Text.Json;
using NAudio.CoreAudioApi;
using NAudio.Wave;
using NAudio.Wave.SampleProviders;
using System.Windows;
using System.Windows.Media;
using System.Windows.Media.Imaging;
namespace FieldTrader;
public static class RecognitionValidation {
 public static async Task Run(string segmentDirectory,string reportDirectory,bool loopback){
  Directory.CreateDirectory(reportDirectory);var lines=new List<string>{"# 真实声音识别验证", "", "数据仅来自同一批录音，重复操作可能使用相同游戏音效；结果不是独立场景准确率。", ""};
  var store=new CatalogStore(Path.Combine(reportDirectory,"test-database"));store.Load();SeedCatalog.Merge(store);var engine=new TemplateRecognitionService();engine.Load(store.Data,store.Root);lines.Add($"模板数：{engine.TemplateCount}；加载失败：{engine.LoadErrors.Count}。");if(engine.TemplateCount<14||engine.LoadErrors.Count>0)throw new InvalidOperationException("声音模板未完整加载");
  using var metadata=JsonDocument.Parse(File.ReadAllText(Path.Combine(segmentDirectory,"..","segments.json")));
  int correct=0,total=0;lines.Add("\n|留出片段|预期|结果|同类距离|异类距离|\n|---|---|---|---|---|");
  foreach(var clip in metadata.RootElement.EnumerateArray().Where(c=>!c.GetProperty("training").GetBoolean())){string name=clip.GetProperty("file").GetString()!,label=clip.GetProperty("label").GetString()!,expected=label=="lion"?store.Data.Items.First(i=>i.Name=="金狮雕像").SoundGroupId:store.Data.Items.First(i=>i.Name=="古董茶壶").SoundGroupId;var audio=AudioFiles.Read(Path.Combine(segmentDirectory,name));var decision=engine.Compare(audio,store.Data);total++;if(decision.Result?.SoundGroupId==expected)correct++;lines.Add($"|{name}|{label}|{decision.Result?.SoundGroupId??"拒绝"}|{decision.Ranking.FirstOrDefault(r=>r.GroupId==expected)?.Distance:F5}|{decision.Ranking.FirstOrDefault(r=>r.GroupId!=expected)?.Distance:F5}|");}
  lines.Add($"\n留出片段正确匹配：{correct}/{total}。这些片段未作为模板加载。\n");
  var random=new Random(47);var negatives=new Dictionary<string,float[]>{{"静音",new float[8000]},{"白噪声",Enumerable.Range(0,8000).Select(_=>(float)((random.NextDouble()*2-1)*.03)).ToArray()},{"1000Hz单音",Enumerable.Range(0,8000).Select(i=>(float)(.02*Math.Sin(2*Math.PI*1000*i/16000))).ToArray()},{"300Hz单音",Enumerable.Range(0,8000).Select(i=>(float)(.02*Math.Sin(2*Math.PI*300*i/16000))).ToArray()}};
  foreach(var (name,samples) in negatives){var decision=engine.Compare(new(samples,16000,DateTimeOffset.Now),store.Data);lines.Add($"负例 {name}：{(decision.Result==null?"拒绝通过":"错误接受")}，最近距离 {decision.Ranking.FirstOrDefault()?.Distance:F4}。");}
    int transformed=0,transformedTotal=0;foreach(var (name,expected) in new[]{("lion-08.wav",store.Data.Items.First(i=>i.Name=="金狮雕像").SoundGroupId),("teapot-06.wav",store.Data.Items.First(i=>i.Name=="古董茶壶").SoundGroupId)}){var original=AudioFiles.Read(Path.Combine(segmentDirectory,name));foreach(double speed in new[]{.9,1.0,1.1}){var samples=new float[(int)(original.Mono.Length/speed)];for(int i=0;i<samples.Length;i++){double p=i*speed;int a=(int)p,b=Math.Min(a+1,original.Mono.Length-1);samples[i]=(float)((original.Mono[a]*(1-(p-a))+original.Mono[b]*(p-a))*.25);}var decision=engine.Compare(new(samples,original.SampleRate,DateTimeOffset.Now),store.Data);transformedTotal++;if(decision.Result?.SoundGroupId==expected)transformed++;}}lines.Add($"\n音量降低到25%、时长变化±10%的合成扰动：{transformed}/{transformedTotal} 正确。（仅鲁棒性检查，不是独立录音。）");
  int falseAccepts=0;for(int seed=0;seed<20;seed++){var rng=new Random(seed);var samples=Enumerable.Range(0,3200+seed*240).Select(_=>(float)((rng.NextDouble()*2-1)*.04)).ToArray();if(engine.Compare(new(samples,16000,DateTimeOffset.Now),store.Data).Result!=null)falseAccepts++;}lines.Add($"\n额外20段随机噪声：错误接受 {falseAccepts}/20。尚未验证真实枪声、脚步声和多人语音。\n");
  foreach(var (label,name) in new[]{(store.Data.Items.First(i=>i.Name=="金狮雕像").SoundGroupId,"金狮雕像.wav"),(store.Data.Items.First(i=>i.Name=="古董茶壶").SoundGroupId,"古董茶壶.wav")}){var audio=AudioFiles.Read(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.MyMusic),name));var detector=new EnergyEventDetector();var decisions=new List<MatchDecision>();for(int i=0;i<audio.Mono.Length;i+=960)foreach(var sound in detector.Push(new(audio.Mono[i..Math.Min(i+960,audio.Mono.Length)],audio.SampleRate,DateTimeOffset.Now)))decisions.Add(engine.Compare(sound,store.Data));lines.Add($"\n完整原录音 {name}：自动检测 {decisions.Count} 段，同类匹配 {decisions.Count(d=>d.Result?.SoundGroupId==label)} 段，拒绝 {decisions.Count(d=>d.Result==null)} 段，错类 {decisions.Count(d=>d.Result!=null&&d.Result.SoundGroupId!=label)} 段。（含训练片段，只验证全流程。）");}
  using var state=new SessionState(store,Application.Current.Dispatcher);var main=new MainWindow(state);var hud=new OverlayWindow(state);main.Show();hud.Show();
  if(loopback&&state.Devices.Count>0){state.Start();await Task.Delay(800);using var enumerator=new MMDeviceEnumerator();using var endpoint=enumerator.GetDevice(state.SelectedDevice!.Id);foreach(var (file,expected) in new[]{("lion-08.wav","金狮雕像"),("teapot-06.wav","古董茶壶")}){int before=state.History.Count;using var reader=new AudioFileReader(Path.Combine(segmentDirectory,file)){Volume=.04f};using var player=new WasapiOut(endpoint,AudioClientShareMode.Shared,false,100);player.Init(reader.ToStereo());player.Play();await Task.Delay(1600);bool ok=state.History.Count>before&&state.Candidates.Any(c=>c.Name==expected);lines.Add($"\n真实 WASAPI 播放→采集→检测→匹配：{expected} {(ok?"通过":"未通过")}。");}await state.StopAsync();}
  state.Publish(engine.Compare(AudioFiles.Read(Path.Combine(segmentDirectory,"lion-08.wav")),store.Data).Result!);await Task.Delay(100);Screenshot(main,Path.Combine(reportDirectory,"lion-main.png"));Screenshot(hud,Path.Combine(reportDirectory,"lion-hud.png"));state.Publish(engine.Compare(AudioFiles.Read(Path.Combine(segmentDirectory,"teapot-06.wav")),store.Data).Result!);await Task.Delay(100);Screenshot(main,Path.Combine(reportDirectory,"teapot-main.png"));Screenshot(hud,Path.Combine(reportDirectory,"teapot-hud.png"));
  File.WriteAllLines(Path.Combine(reportDirectory,"recognition-report.md"),lines);hud.Close();main.Close();if(correct!=total)throw new InvalidOperationException($"留出验证 {correct}/{total}，请检查报告");
 }
 private static void Screenshot(Window window,string path){window.UpdateLayout();var bitmap=new RenderTargetBitmap((int)window.ActualWidth,(int)window.ActualHeight,96,96,PixelFormats.Pbgra32);bitmap.Render(window);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using var output=File.Create(path);encoder.Save(output);}
}


